data.minimal_example:
GifController _controller = GifController(vsync: this);

Gif(
     image: AssetImage("images/animate.gif"),
     controller: _controller,
     autostart: Autostart.no,
     placeholder: (context) => const Text('Loading...'),
     onFetchCompleted: () {
          _controller.reset();
          _controller.forward();
     },
)
